contracts/task_manager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.2 <0.9.0;

contract TaskManager {
    string[] private tasks;

    function addTask(string calldata task) public {
        tasks.push(task);
    }

    function deleteTask(uint256 index) public {
        for (uint256 i = index; i < tasks.length - 1; i++) {
            tasks[i] = tasks[i + 1];
        }

        tasks.pop();
    }

    function getAllTasks() public view returns (string[] memory) {
        return tasks;
    }

    function getTaskCount() public view returns (uint256) {
        return tasks.length;
    }
}

contracts/lesson2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.2 <0.9.0;

import "hardhat/console.sol";

contract Foundation {
    address owner;

    error NotOwner(address expected, address given);

    constructor() {
        owner = msg.sender;
    }

    function donate() external payable {
        console.log("New donate: ", msg.value);
    }

    function withdraw() external {
        // if (msg.sender != owner) {
        //     // revert("You`re not owner");
        //     revert NotOwner(owner, msg.sender);
        // }
        
        require(msg.sender != owner, NotOwner(owner, msg.sender));

        (bool result, ) = payable(owner).call{value: address(this).balance}("");

        if (!result) {
            revert("Withdraw failed");
        }

        console.log("Withdraw successful");
    }
}

